"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""

import re

INPUT_PATH = "/app/input.txt"
OUTPUT_PATH = "/app/output.txt"

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}
ROLE_RE = re.compile(r"^[A-Za-z0-9_-]+$")
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def normalize_path(path):
    """Replace all valid {variable} patterns with {var}."""
    return VAR_RE.sub("{var}", path)


def count_segments(path):
    """Count non-empty segments split on '/'."""
    return len([s for s in path.split("/") if s != ""])


def split_sections(text):
    """Split input into sections separated by blank lines."""
    sections = []
    current = []
    for line in text.split("\n"):
        if line.strip() == "":
            if current:
                sections.append(current)
                current = []
            else:
                # Multiple consecutive blank lines: treat as a section of
                # nothing; keep structure simple by not appending empties.
                pass
        else:
            current.append(line)
    if current:
        sections.append(current)
    return sections


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on malformed lines.

    Returns list of endpoint dicts in input order.
    """
    endpoints = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            break  # hard cutoff
        path, method, role, permission = parts
        if path.strip() == "":
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        if permission.upper() not in VALID_PERMISSIONS:
            break
        role = role.strip()
        if role == "":
            break
        if not ROLE_RE.match(role):
            break
        endpoints.append({
            "path": path,
            "norm": normalize_path(path),
            "method": method,
            "role": role,
            "permission": permission.upper(),
        })
    return endpoints


def parse_base_exclude(lines):
    """Parse BASE/EXCLUDE section."""
    base = None
    exclude = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "base":
            if len(parts) >= 2:
                base = parts[1]
        elif parts[0] == "exclude":
            for r in parts[1:]:
                exclude.add(r)
    return base, exclude


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed lines.

    Returns list of (path, method) tuples in input order.
    """
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if path.strip() == "":
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open(INPUT_PATH, "r") as f:
        text = f.read()

    sections = split_sections(text)

    endpoints = []
    base = None
    exclude = set()
    plan = []

    if len(sections) >= 1:
        endpoints = parse_endpoints(sections[0])
    if len(sections) >= 2:
        base, exclude = parse_base_exclude(sections[1])
    if len(sections) >= 3:
        plan = parse_plan(sections[2])

    # Eligibility: base prefix match + exclude filtering
    eligible = []
    for ep in endpoints:
        if base is not None and not ep["path"].startswith(base):
            continue
        if ep["role"] in exclude:
            continue
        eligible.append(ep)

    # Determine the set of endpoint indices to include.
    include_idx = set()

    if not plan:
        # PLAN empty: include all eligible endpoints.
        for i, ep in enumerate(endpoints):
            if ep in eligible:
                include_idx.add(i)
        # Also handle parent-path inheritance for all eligible endpoints?
        # With PLAN empty, "all eligible endpoints" already covers parents
        # of eligible endpoints that are themselves eligible. The special
        # case for excluded-role-only parents applies to inheritance needs;
        # with PLAN empty there are no specific PLAN endpoints to inherit
        # from, so excluded roles stay filtered out.
    else:
        # For each PLAN endpoint, include matching endpoints and their
        # parent-path endpoints.
        for p_path, p_method in plan:
            p_norm = normalize_path(p_path)
            # Matching endpoints: same normalized path
            for i, ep in enumerate(endpoints):
                if ep["norm"] == p_norm:
                    if ep in eligible:
                        include_idx.add(i)
                    else:
                        # endpoint exists but is not eligible (base or
                        # excluded role); only include if eligible
                        pass
            # Parent paths: any distinct normalized path that is a prefix
            # of p_norm and has at least one eligible endpoint.
            parent_norms = set()
            for ep in eligible:
                if ep["norm"] != p_norm and p_norm.startswith(ep["norm"]):
                    parent_norms.add(ep["norm"])
            for norm in parent_norms:
                # Include all endpoints for this parent path that are
                # eligible.
                for i, ep in enumerate(endpoints):
                    if ep["norm"] == norm and ep in eligible:
                        include_idx.add(i)
                # Special case: parent path whose only endpoints are for
                # excluded roles (not base-filtered) and is needed for
                # inheritance -> include them.
                all_eps_at_norm = [ep for ep in endpoints if ep["norm"] == norm]
                if all_eps_at_norm:
                    non_excluded = [ep for ep in all_eps_at_norm
                                    if ep["role"] not in exclude]
                    if not non_excluded and all_eps_at_norm:
                        # only excluded-role endpoints exist here
                        for i, ep in enumerate(endpoints):
                            if ep["norm"] == norm:
                                include_idx.add(i)

    # Deduplicate: one endpoint per (normalized path, method, role),
    # first encountered in input order.
    seen = set()
    chosen = []
    for i in sorted(include_idx):
        ep = endpoints[i]
        key = (ep["norm"], ep["method"], ep["role"])
        if key in seen:
            continue
        seen.add(key)
        chosen.append(ep)

    # Preserve original variable names: if multiple endpoints share the
    # same normalized path but different variable names, use the first
    # encountered (by input order) variable name.
    # Build a mapping from normalized path -> original path (first
    # occurrence in endpoints list).
    norm_to_original = {}
    for ep in endpoints:
        if ep["norm"] not in norm_to_original:
            norm_to_original[ep["norm"]] = ep["path"]

    for ep in chosen:
        ep["out_path"] = norm_to_original[ep["norm"]]

    # Ordering:
    # 1. path length in segments (longer first)
    # 2. method alphabetical
    # 3. role lexicographic (case-sensitive)
    # 4. permission ALLOW before DENY
    def sort_key(ep):
        return (
            -count_segments(ep["out_path"]),
            ep["method"],
            ep["role"],
            0 if ep["permission"] == "ALLOW" else 1,
        )

    chosen.sort(key=sort_key)

    # Uniqueness on (original path, method, role)
    final = []
    seen2 = set()
    for ep in chosen:
        key = (ep["out_path"], ep["method"], ep["role"])
        if key in seen2:
            continue
        seen2.add(key)
        final.append(ep)

    if final:
        out_lines = ["{} {} {} {}".format(ep["out_path"], ep["method"],
                                          ep["role"], ep["permission"])
                     for ep in final]
        output = "\n".join(out_lines) + "\n"
    else:
        output = "\n"

    with open(OUTPUT_PATH, "w") as f:
        f.write(output)


if __name__ == "__main__":
    main()
