"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""

import re

INPUT_PATH = "/app/input.txt"
OUTPUT_PATH = "/app/output.txt"

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def normalize_path(path):
    """Replace all valid {variable} patterns with {var}."""
    return VAR_RE.sub("{var}", path)


def count_segments(path):
    """Count non-empty segments split on '/'."""
    return len([s for s in path.split("/") if s != ""])


def split_sections(text):
    """Split input into sections separated by blank lines."""
    sections = []
    current = []
    for line in text.split("\n"):
        if line.strip() == "":
            if current:
                sections.append(current)
                current = []
        else:
            current.append(line)
    if current:
        sections.append(current)
    return sections


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on malformed lines.

    A line is malformed if:
      - wrong number of fields (must be exactly 4)
      - path is empty after stripping
      - method is invalid
      - permission is invalid
      - role is empty after stripping
    Returns list of endpoint dicts in input order (up to cutoff).
    """
    endpoints = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            break  # hard cutoff
        path, method, role, permission = parts
        if path.strip() == "":
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        if permission.strip() == "" or permission.upper() not in VALID_PERMISSIONS:
            break
        role = role.strip()
        if role == "":
            break
        endpoints.append({
            "path": path,
            "norm": normalize_path(path),
            "method": method,
            "role": role,
            "permission": permission.upper(),
        })
    return endpoints


def parse_base_exclude(lines):
    """Parse BASE/EXCLUDE section."""
    base = None
    exclude = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "base":
            if len(parts) >= 2:
                base = parts[1]
        elif parts[0] == "exclude":
            for r in parts[1:]:
                exclude.add(r)
    return base, exclude


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed lines.

    A line is malformed if:
      - wrong number of fields (must be exactly 2)
      - path is empty after stripping
      - method is invalid
    Returns list of (path, method) tuples in input order (up to cutoff).
    """
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break  # hard cutoff
        path, method = parts
        if path.strip() == "":
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open(INPUT_PATH, "r") as f:
        text = f.read()

    sections = split_sections(text)

    endpoints = []
    base = None
    exclude = set()
    plan = []

    if len(sections) >= 1:
        endpoints = parse_endpoints(sections[0])
    if len(sections) >= 2:
        base, exclude = parse_base_exclude(sections[1])
    if len(sections) >= 3:
        plan = parse_plan(sections[2])

    def base_ok(ep):
        return base is None or ep["path"].startswith(base)

    def is_eligible(ep):
        return base_ok(ep) and ep["role"] not in exclude

    eligible = [ep for ep in endpoints if is_eligible(ep)]

    # Determine which endpoint indices to include.
    include_idx = set()

    if not plan:
        # PLAN empty: include all eligible endpoints (excluded roles are
        # always filtered out; no inheritance exception applies).
        for i, ep in enumerate(endpoints):
            if is_eligible(ep):
                include_idx.add(i)
    else:
        # PLAN set: (normalized path, method) pairs.
        plan_set = set()
        plan_paths = []  # normalized paths of PLAN entries that exist in ENDPOINTS
        for p_path, p_method in plan:
            p_norm = normalize_path(p_path)
            # PLAN entry is "in ENDPOINTS" if some endpoint shares the
            # normalized path and method.
            if any(ep["norm"] == p_norm and ep["method"] == p_method
                   for ep in endpoints):
                plan_set.add((p_norm, p_method))
                plan_paths.append(p_norm)

        # 1) Endpoints that are directly in PLAN (and eligible).
        for i, ep in enumerate(endpoints):
            if is_eligible(ep) and (ep["norm"], ep["method"]) in plan_set:
                include_idx.add(i)

        # 2) Parent path resolution for each PLAN endpoint (that exists
        #    in ENDPOINTS).
        # Group endpoints by normalized path.
        by_norm = {}
        for i, ep in enumerate(endpoints):
            by_norm.setdefault(ep["norm"], []).append(i)

        for p_norm in plan_paths:
            for norm, idxs in by_norm.items():
                if norm == p_norm:
                    continue
                if not p_norm.startswith(norm):
                    continue
                # norm is a proper normalized prefix of the PLAN path.
                eps = [endpoints[i] for i in idxs]
                eligible_eps = [ep for ep in eps if is_eligible(ep)]
                if eligible_eps:
                    # Parent path has at least one eligible endpoint:
                    # include the eligible endpoints for this path.
                    for i in idxs:
                        if is_eligible(endpoints[i]):
                            include_idx.add(i)
                else:
                    # Special case: parent path whose endpoints are only
                    # for excluded roles (base-OK but role excluded).
                    if eps and all(base_ok(ep) and ep["role"] in exclude
                                   for ep in eps):
                        for i in idxs:
                            include_idx.add(i)

    # Deduplicate: one endpoint per (normalized path, method, role),
    # first encountered in input order.
    seen = set()
    chosen = []
    for i in sorted(include_idx):
        ep = endpoints[i]
        key = (ep["norm"], ep["method"], ep["role"])
        if key in seen:
            continue
        seen.add(key)
        chosen.append(ep)

    # Preserve original variable names: for a normalized path, use the
    # original path of the first endpoint (input order) with that norm.
    norm_to_original = {}
    for ep in endpoints:
        if ep["norm"] not in norm_to_original:
            norm_to_original[ep["norm"]] = ep["path"]

    for ep in chosen:
        ep["out_path"] = norm_to_original[ep["norm"]]

    # Ordering:
    # 1. path length in segments (longer paths first)
    # 2. method (alphabetical)
    # 3. role (lexicographic, case-sensitive)
    # 4. permission (ALLOW before DENY)
    def sort_key(ep):
        return (
            -count_segments(ep["out_path"]),
            ep["method"],
            ep["role"],
            0 if ep["permission"] == "ALLOW" else 1,
        )

    chosen.sort(key=sort_key)

    # Uniqueness on (original path, method, role).
    final = []
    seen2 = set()
    for ep in chosen:
        key = (ep["out_path"], ep["method"], ep["role"])
        if key in seen2:
            continue
        seen2.add(key)
        final.append(ep)

    if final:
        out_lines = ["{} {} {} {}".format(ep["out_path"], ep["method"],
                                          ep["role"], ep["permission"])
                     for ep in final]
        output = "\n".join(out_lines) + "\n"
    else:
        output = "\n"

    with open(OUTPUT_PATH, "w") as f:
        f.write(output)


if __name__ == "__main__":
    main()
